 $pr=gh pr view $r.pr.url --json url,state,isDraft,mergedAt,headRefName,headRefOid,statusCheckRollup|ConvertFrom-Json
 if($LASTEXITCODE -ne 0){throw "PR refresh failed $($r.repo)"}
 $ok=$pr.headRefOid -eq $r.tip -and $pr.state -eq 'OPEN' -and $pr.isDraft -and $null -eq $pr.mergedAt
 $final+=@{repo=$r.repo;observedUtc=[DateTime]::UtcNow.ToString('o');contractMatches=$ok;pr=$pr}
 if(!$ok){throw "PR contract changed $($r.repo)"}
 foreach($check in @($pr.statusCheckRollup|Where-Object conclusion -eq 'FAILURE')){
  $job=($check.detailsUrl -split '/')[-1]
  $ann=gh api "repos/sharpninja/$($r.repo)/check-runs/$job/annotations"|ConvertFrom-Json
  $annotations+=@{repo=$r.repo;job=$job;url=$check.detailsUrl;annotations=$ann;exit=$LASTEXITCODE}
 }
 "$($r.repo): exact tip, OPEN/draft/unmerged"
}
Add-LinesToFile (Join-Path $script:hvEv 'pr-status-final.json') -Content ($final|ConvertTo-Json -Depth 15)|Out-Null
Add-LinesToFile (Join-Path $script:hvEv 'ci-annotations-final.json') -Content ($annotations|ConvertTo-Json -Depth 12)|Out-Null
$annotations|ForEach-Object {[pscustomobject]@{repo=$_.repo;job=$_.job;failureMessages=@($_.annotations|Where-Object annotation_level -eq 'failure'|Select-Object -ExpandProperty message)}}|ConvertTo-Json -Compress
if((Get-FileHash 'docs/Project/QBrain-AI-Rebrand-Implementation-Plan-2026-10-05.md').Hash -ne $script:planHashBefore){throw 'Plan hash changed'}
$script:finalCheckedUtc=[DateTime]::UtcNow.ToString('o')
"FinalCheckUtc=$script:finalCheckedUtc"
